SOURCES={'gamma/check_effective_gamma.py': '"""Exact auxiliary certificates for EG1–EG35; no native-period numerics."""\nfrom pathlib import Path\nfrom fractions import Fraction as F\nfrom math import comb\nimport json\nimport sympy as s\n\nP = Path(__file__).resolve().parent\nchecks = []\n\ndef check(name, value):\n    if not bool(value):\n        raise ArithmeticError(name)\n    checks.append(name)\n\ndef equal(name, left, right):\n    check(name, s.simplify(left-right) == 0)\n\ndef log_interval(x, terms=40):\n    x=F(x)\n    if not x>1:\n        raise ValueError(\'This certificate uses x>1.\')\n    r=(x-1)/(x+1)\n    lo=2*sum((r**(2*j+1)/F(2*j+1) for j in range(terms)),F(0))\n    tail=2*r**(2*terms+1)/(F(2*terms+1)*(1-r*r))\n    return lo,lo+tail\n\na=lambda j:F(comb(2*j,j)**2,16**j)\nfor cap,z,num,target,fp in [\n    (F(11,10),F(11,20),12,F(3,10000),F(3,5)),\n    (F(3,2),F(16,25),10,F(1,100),F(3,4))]:\n    check(f\'aspect separation {cap}\',sum(((4*j-cap)*a(j)*z**j for j in range(num+1)),F(0))>target)\n    check(f\'derivative floor {cap}\',sum((j*a(j)*z**(j-1) for j in range(1,num+1)),F(0))>fp)\ncheck(\'first density cap\',F(70000,6561)<11)\ncheck(\'second density cap\',F(12500,729)<18)\nl2,u2=log_interval(2)\nl3,u3=log_interval(3)\nl45,u45=log_interval(F(45,32))\ncheck(\'Gamma lower envelope constant\',F(3,2)*l2>F(37,48))\ncheck(\'Gamma upper envelope constant\',F(1,2)*u2+F(2,3)<l3)\ncheck(\'log 2 upper\',u2<F(6932,10000))\ncheck(\'log 184320 upper\',17*u2+u45<F(97,8))\nfor d, bound in [(11,83),(18,111)]:\n    const=17*u2+u45+36*u2+4*d+F(1,640)+1\n    check(f\'uniform odd-inclusive constant {bound}\',const<bound)\ncheck(\'positive scalar error below 13\',5+F(23,2)*u2<13)\ncheck(\'small-y polynomial exclusion\',64*F(22,7)**2/(4*36**2)<F(1,4))\ncheck(\'tail cutoff guard\',5*16*u2-F(3,2)*256 < -20)\ncheck(\'quantile constant\',F(720*4*3*3,64*2)<203)\ncheck(\'entropy floor\',F(1,392)>F(1,2048))\n\nr,A,B,fp=s.symbols(\'r A B fp\',positive=True)\nu=4/(s.pi*(1+r)*A)\nv=4/(s.pi*(1-r)*A)\nt=4*r*r*fp/A\nW=v*v-u*u\nequal(\'complete endpoint width\',W,64*r/(s.pi**2*(1-r*r)**2*A*A))\nequal(\'density expression\',W**2/(16*t*u*u*v),(1+r)/(s.pi*(1-r*r)**3*fp))\n# Entropy exponent before exponentiation uses independent log symbols.\nlp,lw,lg,lpi,lc=s.symbols(\'lp lw lg lpi lc\')\nentropy=lpi-lp+s.Rational(1,4)*(2*lp-2*lw)+s.Rational(1,2)*(2*lp-2*lg)\nequal(\'entropy exponent\',entropy.subs(lg,2*lw-lc),lpi+lc+lp/2-s.Rational(5,2)*lw)\n\nalpha,theta,q=s.symbols(\'alpha theta q\',positive=True)\nfor b in [1,2,4,7]:\n    T=s.zeros(b+1)\n    U=s.zeros(b+1)\n    for i in range(b+1):\n        for j in range(i,b+1):\n            coeff=s.binomial(j,i)*s.rf(alpha+i+1,j-i)/(theta*q)**(j-i)\n            T[i,j]=(-1)**(j-i)*coeff\n            U[i,j]=coeff\n    check(f\'complete Laguerre coefficient inverse b={b}\',(T*U-s.eye(b+1)).applyfunc(s.simplify)==s.zeros(b+1))\n\n# Exact finite examples retain every source coordinate and cross term.\n# The Gaussian auxiliary measure is used solely to check the finite identities.\ndef gaussian_moment(j):\n    if j%2:\n        return s.Integer(0)\n    return s.factorial2(j-1) if j else s.Integer(1)\n\nfixtures=[]\nfor band in [1,2,3]:\n    scale=s.Integer(5)\n    for M in range(band,band+4):\n        G=s.Matrix(M+1,M+1,lambda i,j:gaussian_moment(i+j))\n        J=s.zeros(band,M+1)\n        for i in range(band):J[i,i]=scale**i\n        Cov=J*G.inv()*J.T\n        H=Cov.inv()\n        section=G.inv()*J.T*H\n        check(f\'full attained jet M={M},b={band}\',J*section==s.eye(band))\n        check(f\'complete source metric M={M},b={band}\',section.T*G*section==H)\n        Z=s.eye(M+1)[:,band:]\n        check(f\'full relation orthogonality M={M},b={band}\',Z.T*G*section==s.zeros(M+1-band,band))\n        L=M-band\n        GL=G[:L+1,:L+1]\n        e=s.eye(L+1)[:,0]\n        scalar=(e.T*GL.inv()*e)[0]\n        coeff=GL.inv()*e/scalar\n        y=s.symbols(\'y\')\n        Hpoly=sum(coeff[i]*y**i for i in range(L+1))\n        check(f\'kernel value L={L},b={band}\',Hpoly.subs(y,0)==1)\n        equal(f\'kernel norm L={L},b={band}\',(coeff.T*GL*coeff)[0],1/scalar)\n        R=s.zeros(M+1,band)\n        x=s.symbols(\'x\')\n        recip=s.series(1/Hpoly.subs(y,scale*x),x,0,band).removeO()\n        for c in range(band):\n            truncated=s.Poly(s.expand(x**c*recip),x)\n            bpoly=sum(truncated.nth(i)*x**i for i in range(band))\n            lift=s.Poly(s.expand(Hpoly*bpoly.subs(x,y/scale)),y)\n            for i in range(M+1): R[i,c]=lift.nth(i)\n        check(f\'simultaneous reciprocal right inverse M={M},b={band}\',J*R==s.eye(band))\n        difference=R-section\n        check(f\'exact minimum excess M={M},b={band}\',R.T*G*R-H==difference.T*G*difference)\n        fixtures.append({\'band\':band,\'source_degree\':M,\'auxiliary_measure\':\'Gaussian moments without scalar mass; finite map identity only\'})\n\nnegative=0\nfor invalid in [lambda:check(\'negative control false endpoint\',F(70000,6561)<10),\n                lambda:check(\'negative control missing parity\',s.Integer(1)==0)]:\n    try:invalid()\n    except ArithmeticError:negative+=1\n    else:raise ArithmeticError(\'A negative control was accepted.\')\n\ndata={\'status\':\'passed\',\'exact_checks\':len(checks),\'negative_controls_rejected\':negative,\n      \'proof\':\'EFFECTIVE_GAMMA_AND_JET_PROOF.md\',\'scope\':\'Exact constants and finite full-source maps. Analytic inequalities are proved in EG1–EG35; these finite examples do not replace them.\',\n      \'sharper_constants\':{\'aspect_11_over_10\':83,\'aspect_3_over_2\':111},\n      \'checks\':checks,\'fixtures\':fixtures}\n(P/\'VERIFICATION.json\').write_text(json.dumps(data,indent=2)+\'\\n\',encoding=\'utf-8\')\nprint(json.dumps({k:data[k] for k in [\'status\',\'exact_checks\',\'negative_controls_rejected\',\'sharper_constants\']}))\n', 'localization/check_localization_exact.py': "from pathlib import Path\nimport hashlib\nimport json\nimport math\nimport sympy as s\n\nout = Path(__file__).resolve().parent\ny,z,x=s.symbols('y z x')\nchecks=[]\ndef check(name, truth):\n    if not bool(truth):\n        raise ArithmeticError(name)\n    checks.append(name)\ndef zero(a):\n    if isinstance(a,s.MatrixBase):\n        return all(s.cancel(v)==0 for v in a)\n    return s.cancel(a)==0\ndef pp(a):\n    return s.div(s.together(a).as_numer_denom()[0],s.together(a).as_numer_denom()[1],y)[0]\ndef rem(a,Q):\n    return s.rem(a,Q,y)\n\n# Complete finite resolvent and strictly raising operator, all entries.\nfor q in range(2,9):\n    D=s.zeros(q)\n    for j in range(1,q):D[j-1,j]=j\n    E=s.Matrix([(z*y)**j/s.factorial(j) for j in range(q)])\n    Em=s.Matrix([z**j/s.factorial(j) for j in range(q)])\n    lam=s.Matrix([[s.factorial(n)*z**(-n-1) for n in range(q)]])\n    R=s.zeros(q)\n    for n in range(q):\n        for j in range(1,q-n): R[n+j,n]=s.factorial(n)*z**(j-1)/s.factorial(n+j)\n    resolvent=sum((D**j/z**(j+1) for j in range(q)),s.zeros(q))\n    check(f'resolvent_complete_q{q}',zero(resolvent-Em*lam+R))\n    check(f'raising_diagonal_zero_q{q}',all(R[i,j]==0 for i in range(q) for j in range(i,q)))\n    check(f'resolvent_inverse_q{q}',zero((z*s.eye(q)-D)*resolvent-s.eye(q)))\n    for r in (2,3,7):\n        top=sum(s.Rational((q*r)**j,s.factorial(j)) for j in range(1,q))\n        check(f'finite_exponential_bound_q{q}_r{r}',top <= (3*r)**q)\n        norms=[sum(abs(R[i,j].subs(z,r))*q**(i-j) for i in range(q)) for j in range(q)]\n        check(f'raising_column_bound_q{q}_r{r}',max(norms)<=top/r)\n\n# Exact poles including repeated poles; every pole is retained.\nfor q in (2,3,4,5):\n    D=s.zeros(q)\n    for j in range(1,q):D[j-1,j]=j\n    Em=s.Matrix([z**j/s.factorial(j) for j in range(q)])\n    lam=s.Matrix([[s.factorial(n)*z**(-n-1) for n in range(q)]])\n    R=s.zeros(q)\n    for n in range(q):\n        for j in range(1,q-n):R[n+j,n]=s.factorial(n)*z**(j-1)/s.factorial(n+j)\n    for poles in (((2,1),),((2,2),),((2,1),(-3,1)),((2,2),(-3,1))):\n        b=s.prod((1-z/a)**m for a,m in poles)\n        invpoly=s.series(1/b,z,0,q).removeO()\n        inv=sum((invpoly.coeff(z,j)*D**j for j in range(q)),s.zeros(q))\n        B=s.zeros(q);LL=s.zeros(q)\n        for a,m in poles:\n            # Integral at all finite poles; coefficient formulas evaluate exactly.\n            def residue_matrix(M):\n                return M.applyfunc(lambda v:s.residue(v/b,z,a))\n            B+=residue_matrix(R)\n            piece=residue_matrix(Em*lam)\n            LL+=piece\n            check(f'pole_range_rank_q{q}_{poles}_{a}',piece.rank()<=m)\n        check(f'full_residue_identity_q{q}_{poles}',zero(B-LL-inv))\n        check(f'full_residue_rank_q{q}_{poles}',LL.rank()<=sum(m for _,m in poles))\n\n# Polynomial parts, complete fibres, inverse, and the retained action defect.\nfor q in range(2,9):\n    Q=s.prod(y-s.Rational(j+1,4*q) for j in range(q)).expand()\n    def U(F):return pp(Q*F/y**q).expand()\n    def Ui(F):return pp(y**q*F/Q).expand()\n    for j in range(q):\n        e=y**j\n        check(f'triangular_inverse_q{q}_j{j}',zero(Ui(U(e))-e))\n        lhs=rem(y*U(e),Q)-U(rem(y*e,y**q))\n        check(f'action_defect_q{q}_j{j}',zero(lhs+Q.coeff(y,q-j-1)))\n    for j in range(q+1):\n        check(f'full_affine_fibre_q{q}_j{j}',zero(U(y**q*y**j)-Q*y**j))\n    # Complete homogeneous/Newton coefficient remainder bound.\n    for j in range(2*q+1):\n        rr=s.Poly(rem(y**j,Q),y)\n        check(f'Newton_full_remainder_q{q}_j{j}',sum(abs(v) for v in rr.all_coeffs())<=s.Rational(3,2)**j)\n\n# Exact actual quartet polynomial map (small algebraic test, no analytic guard claimed).\nfor k in (1,):\n    q=(k+1)**2\n    delta=s.Rational(1,4);gamma=s.Integer(3)\n    roots=[(2*b-k)*gamma-s.I*(2*a-k)*delta for a in range(k+1) for b in range(k+1)]\n    Q=s.prod(y-w for w in roots).expand()\n    for j in range(q):\n        U=lambda F:pp(Q*F/y**q).expand()\n        lhs=rem(y*U(y**j),Q)-U(rem(y**(j+1),y**q))\n        check(f'original_quartet_action_k{k}_j{j}',zero(lhs+Q.coeff(y,q-j-1)))\n    check(f'original_quartet_opposite_pairing_k{k}',zero(Q.subs(y,-y)-Q))\n\n# Full source-to-image identity, retaining all boundary factors.\nfor d,Dg in ((2,2),(3,2),(4,3)):\n    DD=s.prod(y-(j+1) for j in range(d)).expand()\n    OO=s.prod(y+(j+1) for j in range(Dg)).expand()\n    Q=DD*OO;q=d+Dg\n    for j in range(q+2):\n        check(f'word_full_remainder_{d}_{Dg}_{j}',zero(rem(DD*y**j,Q)-DD*rem(y**j,OO)))\n    for j in range(Dg):\n        check(f'image_inverse_map_{d}_{Dg}_{j}',zero(pp(y**q*DD*y**j/Q)-pp(y**q*y**j/OO)))\n\n# Exact isometric compression with non-diagonal full spectral matrix.\nL=s.diag(1,2,3,4)\nIg=s.Matrix([[1,0],[1,0],[0,1],[0,1]])\nB=s.Matrix([[4,1,0,1],[1,5,1,0],[0,1,6,1],[1,0,1,7]])\nHj=L*L;Hi=L*B*L\nC=s.diag(1/s.sqrt(5),s.Rational(1,5))\nV=L*Ig*C\ncheck('exact_original_frame_isometry',zero(V.T*V-s.eye(2)))\ncheck('exact_noncommuting_compression',zero(V.T*B*V-C*Ig.T*Hi*Ig*C))\ncheck('noncommuting_control_is_nontrivial',not zero(Hi*Hj-Hj*Hi))\nHsj=Ig.T*Hj*Ig;Hsi=Ig.T*Hi*Ig\nRR=s.Matrix([[s.Rational(3,5),s.Rational(4,5)]])\nQj=(RR*Hsj.inv()*RR.T).inv();Qi=(RR*Hsi.inv()*RR.T).inv()\nQjs=s.sqrt(Qj[0,0]);WW=C*RR.T*Qjs\nAs=C*Hsi*C\ncheck('complete_quotient_isometry',zero(WW.T*WW-s.eye(1)))\ncheck('complete_quotient_inverse_compression',zero(WW.T*As.inv()*WW-Qjs**2*Qi.inv()))\n\n# Sharp finite exceptional contribution; exact rational logarithm coordinates.\nfor m in range(3,12):\n    for c in range(1,(m+1)//2):\n        BB=s.Integer(24);dd=s.Rational(5,3);AA=s.Rational(1,7)\n        vals=[s.Integer(0)]*c+[dd]*(m-2*c)+[BB]*c\n        exceptional=sum(abs(v-dd) for v in vals)\n        check(f'exceptional_sharp_m{m}_c{c}',exceptional==c*BB)\n        check(f'exceptional_bound_m{m}_c{c}',exceptional<=m*AA+c*BB)\n\n# Finite Laguerre coefficient inversion with literal half-integral alpha.\nfor q,b in ((40,4),(80,8),(120,12)):\n    n=q-b;alpha=s.Rational(4*n-1,2)\n    # theta*q is a symbolic positive scale; algebra is independent of its value.\n    t=s.symbols('theta_q',positive=True)\n    T=s.zeros(b+1);Ti=s.zeros(b+1)\n    for j in range(b+1):\n        for i in range(j+1):\n            a=s.binomial(j,i)*s.rf(alpha+i+1,j-i)/t**(j-i)\n            T[i,j]=(-1)**(j-i)*a;Ti[i,j]=a\n    check(f'full_Laguerre_inverse_q{q}_b{b}',zero(T*Ti-s.eye(b+1)))\n\nnegative=[]\ndef reject(name, false_statement):\n    if bool(false_statement):raise ArithmeticError('negative control accepted: '+name)\n    negative.append(name)\nreject('omitting_action_defect',zero(s.rem(y*pp((y**3+y+1)*y**2/y**3),y**3+y+1,y)))\nreject('omitting_exceptional_quotient',sum(abs(v-2) for v in [0,2,2,24])<=0)\nreject('omitting_nonzero_symbol_poles',zero((s.eye(3)-s.Matrix([[0,1,0],[0,0,2],[0,0,0]])/2).inv()))\n\nreceipt={'scope':'Exact auxiliary identities and finite algebraic checks supporting LX1–44; no native-period Gram evaluation or scalar Gamma certificate claimed.',\n         'passed':len(checks),'negative_controls_rejected':len(negative),'checks':checks,'negative_controls':negative,\n         'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}\n(out/'EXACT_CHECKS.json').write_text(json.dumps(receipt,indent=2)+'\\n',encoding='utf-8')\nprint(json.dumps({k:receipt[k] for k in ('passed','negative_controls_rejected','scope')}))\n", 'evolution/check_evolution.py': '"""Independent exact identities plus labelled numerical stress tests for CE1--29."""\nfrom pathlib import Path\nimport json\nimport sympy as s\nimport numpy as np\nfrom scipy.linalg import expm, svdvals\n\nHERE = Path(__file__).resolve().parent\nexact = []\nnumerical = []\nnegative = []\n\ndef equal(name, actual, expected):\n    diff = actual - expected\n    if isinstance(diff, s.MatrixBase):\n        good = all(s.cancel(v) == 0 for v in diff)\n    else:\n        good = s.simplify(diff) == 0\n    if not good:\n        raise ArithmeticError(name + \': \' + str(diff))\n    exact.append(name)\n\ndef numeric(name, lhs, rhs, tol=1e-10):\n    lhs, rhs = float(lhs), float(rhs)\n    if lhs > rhs + tol * max(1., abs(rhs)):\n        raise ArithmeticError(f\'{name}: {lhs} > {rhs}\')\n    numerical.append({\'name\': name, \'lhs\': lhs, \'rhs\': rhs})\n\ndef rejected(name, residual):\n    if isinstance(residual, s.MatrixBase):\n        nonzero = any(s.simplify(v) != 0 for v in residual)\n    else:\n        nonzero = s.simplify(residual) != 0\n    if not nonzero:\n        raise ArithmeticError(\'Negative control failed: \' + name)\n    negative.append(name)\n\nT, eps, v = s.symbols(\'T eps v\', nonnegative=True)\nintegrand = (1 + (T-v)*eps)*(1+v*eps)/(1+T*eps)\nequal(\'CE13 exact weighted Duhamel integral\', s.integrate(integrand, (v,0,T)),\n      T+eps**2*T**3/(6*(1+T*eps)))\nx,y,E,t,w = s.symbols(\'x y E t w\', real=True)\n# General rank-one two-dimensional matrix, retaining its complex trace.\nz=x+s.I*y\nA=s.Matrix([[z,w],[0,0]])\nS=s.eye(2)+s.I*t*A\nequal(\'CE17 shear characteristic sum\', s.trace(S.H*S), 2+t*t*(x*x+y*y+w*w)-2*t*y)\nequal(\'CE17 shear characteristic product\', (S.H*S).det(), (1-t*y)**2+t*t*x*x)\nequal(\'rank-one square including trace\', A*A, z*A)\n\ndef givens(n, i,j,c,d):\n    r=s.eye(n)\n    r[i,i]=r[j,j]=c\n    r[i,j]=-d\n    r[j,i]=d\n    return r\n\nn=4\nQ=(givens(n,0,2,s.Rational(3,5),s.Rational(4,5))\n   *givens(n,1,3,s.Rational(5,13),s.Rational(12,13))\n   *givens(n,0,1,s.Rational(8,17),s.Rational(15,17))\n   *givens(n,1,2,s.Rational(7,25),s.Rational(24,25)))\nQ=s.diag(1,s.I,1,1)*Q\nJ=Q[:,:2]\nP=J*J.H\nK=s.eye(n)-P\ne=s.eye(n)[:,0]\nf=s.eye(n)[:,1]\nC=s.Matrix([[1,s.I,0,s.Rational(1,3)],[-s.I,-2,s.Rational(1,2),0],\n            [0,s.Rational(1,2),3,-s.I],[s.Rational(1,3),0,s.I,1]])\nepsilon=s.Rational(7,3)\nR=epsilon*f*e.H\nM=C+R\nu=J.H*e\nv=J.H*f\nRB=J.H*R*J\nCB=J.H*C*J\nMB=J.H*M*J\nzB=s.trace(RB)\naa=(u.H*u)[0]\ndd=(v.H*v)[0]\nrr=(u.H*v)[0]\nalpha=(e.H*K*e)[0]\nD=J.H*M*K*M*J\n\nequal(\'full source isometry\', Q.H*Q, s.eye(n))\nequal(\'observed exact isometry\', J.H*J, s.eye(2))\nequal(\'kernel projection idempotent\', K*K,K)\nequal(\'complete rank-one square zero\', R*R,s.zeros(n))\nequal(\'observed rank-one square\', RB*RB,zB*RB)\nequal(\'observed complex trace\',zB,epsilon*rr)\nequal(\'opposite complete source components\',rr,-(e.H*K*f)[0])\nequal(\'leakage alpha\',alpha,1-aa)\nequal(\'observed compression\',MB,CB+RB)\nequal(\'second-order hidden defect\',J.H*M*M*J-MB*MB,D)\nequal(\'quadratic rank-one defect cancellation\',J.H*R*K*R*J,-zB*RB)\nequal(\'complete defect expansion\',D,J.H*C*K*C*J+J.H*C*K*R*J+J.H*R*K*C*J-zB*RB)\nequal(\'inverse defect second coefficient\',MB*MB-J.H*M*M*J,-D)\nrejected(\'discarding complex projected trace\',RB*RB)\nrejected(\'identifying full and compressed second derivative\',D)\nrejected(\'commuting selfadjoint and rank-one parts\',C*R-R*C)\nrejected(\'assigning measured evolution its intrinsic inverse\',D)\n\n# The same original objects in a nonunitary coefficient frame.\nF=s.Matrix([[2,s.Rational(1,3),0,0],[0,3,s.Rational(1,2),0],\n            [0,0,s.Rational(1,2),s.I/4],[0,0,0,5]])\nG=F.H*F\nJc=F.inv()*J\nMc=F.inv()*M*F\nLam=J.H*F\nLc=G.inv()*Lam.H*(Lam*G.inv()*Lam.H).inv()\nPc=Lc*Lam\nequal(\'nonunitary frame original quotient metric\',(Lam*G.inv()*Lam.H).inv(),s.eye(2))\nequal(\'nonunitary frame minimum section\',Lc,Jc)\nequal(\'nonunitary frame source isometry\',Jc.H*G*Jc,s.eye(2))\nequal(\'nonunitary frame compression\',Lam*Mc*Lc,MB)\nequal(\'nonunitary frame full-kernel defect\',Lam*Mc*(s.eye(n)-Pc)*Mc*Lc,D)\nequal(\'original source projection\',Pc,F.inv()*P*F)\n\n# Both signed Taylor series preserve every noncommuting word.\ndef exp_series(mat, degree):\n    return [s.eye(mat.rows)]+[(s.I**j)*mat**j/s.factorial(j) for j in range(1,degree+1)]\nfull=exp_series(M,4)\nobs=[J.H*term*J for term in full]\ncomp=exp_series(MB,4)\nequal(\'first measured derivative\',obs[1],comp[1])\nequal(\'second measured derivative difference\',obs[2]-comp[2],-D/2)\nequal(\'third measured derivative difference\',obs[3]-comp[3],\n      -s.I*(J.H*M**3*J-MB**3)/6)\nfor j in range(1,5):\n    inv_coeff=sum((((-1)**i)*comp[i]*comp[j-i] for i in range(j+1)),s.zeros(2))\n    equal(f\'intrinsic inverse coefficient {j}\',inv_coeff,s.zeros(2))\n    measured_coeff=sum((((-1)**i)*obs[i]*obs[j-i] for i in range(j+1)),s.zeros(2))\n    defect_coeff=-sum((((-1)**i)*J.H*full[i]*K*full[j-i]*J for i in range(j+1)),s.zeros(2))\n    equal(f\'complete observed inverse defect coefficient {j}\',measured_coeff,defect_coeff)\n\ndef arr(mat): return np.array(mat.evalf(18).tolist(),dtype=np.complex128)\nJn,Cn,Rn,Kn=map(arr,(J,C,R,K))\ndef norm(mat): return float(np.linalg.norm(mat,2))\ndef rank_bound(T,ee,zz,cc):\n    d=cc*np.exp(T*abs(zz))*(T+ee*ee*T**3/(6*(1+T*ee)))\n    return d, np.exp(T*abs(zz))*(d/(1-d)+T*abs(zz)/2)\n\nfor scale in (0.1,1.,20.,100.):\n    rfull=scale*Rn\n    mfull=Cn+rfull\n    rb=Jn.conj().T@rfull@Jn\n    mb=Jn.conj().T@mfull@Jn\n    ef=norm(rfull)\n    eb=norm(rb)\n    zz=np.trace(rb)\n    cc=norm(Cn)\n    aa=float(aa)\n    dd=float(dd)\n    al=float(alpha)\n    for TT in (0.0001,0.001,0.01):\n        df,bf=rank_bound(TT,ef,0,cc)\n        db,bb=rank_bound(TT,eb,zz,cc)\n        if max(df,db)>=1: continue\n        AF=(1+TT*ef)/(1+TT*eb)*bf\n        AB=bb\n        h=abs(zz)/eb\n        sh=(np.sqrt(4+(TT*eb)**2)+TT*eb)/2\n        eta=2*AB+2*h\n        for sg in (-1,1):\n            tt=sg*TT\n            uu=Jn.conj().T@expm(1j*tt*mfull)@Jn\n            vv=expm(1j*tt*mb)\n            shear=np.eye(2)+1j*tt*rb\n            prefix=f\'scale {scale}, t {tt}\'\n            numeric(prefix+\' full finite Duhamel\',norm(uu-shear),(1+TT*eb)*AF)\n            numeric(prefix+\' intrinsic finite Duhamel\',norm(vv-shear),(1+TT*eb)*AB)\n            numeric(prefix+\' exact connecting estimate\',norm(uu-vv),(1+TT*eb)*(AF+AB))\n            numeric(prefix+\' full shear error\',abs(norm(uu)/sh-1),2*AF+2*h)\n            numeric(prefix+\' intrinsic shear error\',abs(norm(vv)/sh-1),eta)\n            memory=Jn.conj().T@expm(-1j*tt*mfull)@Kn@expm(1j*tt*mfull)@Jn\n            numeric(prefix+\' exact inverse defect numerical residual\',\n                    norm((Jn.conj().T@expm(-1j*tt*mfull)@Jn)@uu-np.eye(2)+memory),1e-11)\n            # Full hidden propagator bound, retaining C and R in its generator.\n            hidden=Kn@mfull@Kn\n            actual=norm(expm(1j*tt*hidden))\n            numeric(prefix+\' hidden propagator\',actual,np.exp(TT*ef*np.sqrt(al*(1-dd))))\n            sv=svdvals(vv)\n            numeric(prefix+\' exact intrinsic inverse singular value\',\n                    abs(sv[-1]*norm(expm(-1j*tt*mb))-1),1e-11)\n            if eta<1:\n                numeric(prefix+\' smallest singular lower bound\',1/((1+eta)*sh),sv[-1])\n                numeric(prefix+\' smallest singular upper bound\',sv[-1],1/((1-eta)*sh))\n                numeric(prefix+\' condition upper bound\',sv[0]/sv[-1],(1+eta)**2*sh**2)\n                numeric(prefix+\' condition lower bound\',(1-eta)**2*sh**2,sv[0]/sv[-1])\n        # The exact two singular values of the original finite rank-one shear.\n        tr=2+TT*TT*eb*eb-2*TT*zz.imag\n        det=abs(1+1j*TT*zz)**2\n        vals=svdvals(np.eye(2)+1j*TT*rb)**2\n        numeric(f\'{scale},{TT} finite complex shear sum\',abs(sum(vals)-tr),1e-11)\n        numeric(f\'{scale},{TT} finite complex shear product\',abs(np.prod(vals)-det),1e-11)\n\nreceipt={\'exact_identities\':len(exact),\'exact_checks\':exact,\n         \'numerical_inequality_checks\':len(numerical),\'numerical_checks\':numerical,\n         \'negative_controls\':negative,\n         \'scope\':\'Exact finite rank-one, original-metric, noncommuting and hidden-source identities; auxiliary numerical stress tests are not native-period computations and do not establish the conductor asymptotics.\'}\n(HERE/\'VERIFICATION.json\').write_text(json.dumps(receipt,indent=2)+\'\\n\',encoding=\'utf-8\')\nprint(json.dumps({k:receipt[k] for k in (\'exact_identities\',\'numerical_inequality_checks\',\'negative_controls\')},indent=2))\n', 'current/current_checks.py': '#!/usr/bin/env python3\n"""Exact full-source checks, independent finite auxiliary fixtures.\nGamma mass is retained as a common positive scalar when testing invariance.\nThe roots/observations are not native xi zeros or native periods.\n"""\nfrom __future__ import annotations\nimport json, hashlib, sys, math\nfrom pathlib import Path\nfrom itertools import combinations\nimport sympy as s\nY=s.Symbol(\'y\', real=True)\nI=s.I\nchecks=[]; controls=[]; records=[]\ndef clean(M):\n    return M.applyfunc(lambda z:s.cancel(s.expand_complex(z)))\ndef check(name, condition):\n    if not bool(condition): raise ArithmeticError(name)\n    checks.append(name)\ndef eq(name,a,b):\n    if isinstance(a,s.MatrixBase) or isinstance(b,s.MatrixBase):\n        a,b=s.Matrix(a),s.Matrix(b)\n        check(name,a.shape==b.shape and all(s.cancel(z)==0 for z in a-b))\n    else: check(name,s.simplify(a-b)==0)\ndef ispos(M):\n    return all(s.simplify(z)==0 for z in M-M.H) and all(s.simplify(s.det(M[:j,:j]))>0 for j in range(1,M.rows+1))\ndef isnonneg(M):\n    if any(s.simplify(z)!=0 for z in M-M.H):return False\n    for j in range(1,M.rows+1):\n        for ix in combinations(range(M.rows),j):\n            if s.simplify(s.det(M.extract(ix,ix)))<0:return False\n    return True\ndef sqrt_up(x, digits=36):\n    x=s.cancel(x)\n    if not bool(x>=0):raise ArithmeticError(\'negative square-root input\')\n    num,den=map(int,s.fraction(x));scale=10**digits\n    q=math.isqrt((num*scale*scale)//den)\n    if q*q*den==num*scale*scale:return s.Rational(q,scale)\n    return s.Rational(q+1,scale)\ndef coeff(p,n):\n    pp=s.Poly(s.expand(p),Y)\n    return s.Matrix([pp.nth(j) for j in range(n)])\ndef gamma_polys(n):\n    pp=[s.Integer(1),Y]\n    for j in range(1,n):pp.append(s.expand(Y*pp[-1]-j*s.Rational(2*j-1,2)*pp[-2]))\n    return pp[:n+1]\ndef hn(n):return s.factorial(n)*s.rf(s.Rational(1,2),n)\npp=gamma_polys(12)\nHs={}\ndef gram_source(n):\n    if n not in Hs:\n        P=s.Matrix.hstack(*(coeff(p,n+1) for p in pp[:n+1]));Pinv=P.inv()\n        Hs[n]=Pinv.T*s.diag(*(hn(j) for j in range(n+1)))*Pinv\n    return Hs[n]\ndef rem(p,Q):return s.rem(s.Poly(p,Y),s.Poly(Q,Y)).as_expr()\ndef qframe(Q,N):\n    q=int(s.degree(Q,Y));bs=[coeff(rem(p,Q),q) for p in pp[:N+2]]\n    cov=sum((bs[j]*bs[j].H/hn(j) for j in range(N+1)),s.zeros(q))\n    return cov.inv(),bs\n\ndef relnorm(Q,t):\n    n=int(s.degree(Q,Y)+t)\n    R=s.Matrix.hstack(*(coeff(Q*Y**j,n+1) for j in range(t+1)))\n    H=R.H*gram_source(n)*R\n    if t==0:return H[0,0]\n    return s.cancel(H[t,t]-(H[t,:t]*H[:t,:t].inv()*H[:t,t])[0])\n\ndef fixture(d,g,aa,v,N,tag,augment=False):\n    print(\'START\',tag,flush=True,file=sys.stderr)\n    Qlo=Y**2+d*d\n    Qup=s.expand(((Y-g)**2+d*d)*((Y+g)**2+d*d))\n    T=lambda p:s.expand(aa[0]*p.subs(Y,Y+g)+aa[1]*p.subs(Y,Y-g))\n    CA=clean(s.Matrix.hstack(*(coeff(rem(T(Y**j),Qlo),2) for j in range(4))))\n    for j in range(max(0,N-3)):eq(tag+\' whole relation \'+str(j),rem(T(Qup*Y**j),Qlo),0)\n    La=CA\n    if augment:\n        for j in range(4):\n            row=s.eye(4)[j,:]\n            if La.col_join(row).rank()>2:\n                La=La.col_join(row);break\n    check(tag+\' observation rank\',La.rank()==La.rows)\n    G,bs=qframe(Qup,N);D=N-v;Gl,bl=qframe(Qlo,D)\n    M=s.Matrix.hstack(*(coeff(rem(Y**(j+1),Qup),4) for j in range(4)))\n    X=s.Matrix.hstack(bs[N],bs[N+1]);EF=X.H*G*X\n    eq(tag+\' outgoing parity\',EF[0,1],0);check(tag+\' outgoing positive\',ispos(EF))\n    normN=hn(N) if N==3 else hn(N)*(1-hn(N)/relnorm(Qup,N-4))\n    eq(tag+\' exact last source minimum\',EF[0,0],normN)\n    eq(tag+\' exact raised source minimum\',EF[1,1],relnorm(Qup,N-3)-hn(N+1))\n    R=bs[N+1]*bs[N].H*G/hn(N);C=M-R\n    eq(tag+\' nilpotent outgoing\',R*R,s.zeros(4))\n    eq(tag+\' full selfadjoint compression\',G*C,C.H*G)\n    current=I*(G*M-M.H*G)\n    eq(tag+\' original physical current\',current,I*(G*R-R.H*G))\n    QB=clean(clean(La*G.inv()*La.H).inv());Lift=clean(G.inv()*La.H*QB);P=clean(Lift*La)\n    eq(tag+\' original minimum lift\',La*Lift,s.eye(La.rows))\n    eq(tag+\' original metric lift\',Lift.H*G*Lift,QB)\n    OX=clean(X.H*La.H*QB*La*X)\n    check(tag+\' observed outgoing positive\',ispos(OX))\n    check(tag+\' projection contraction\',isnonneg(EF-OX))\n    Wform=clean(Lift.H*current*Lift);Wop=clean(QB.inv()*Wform)\n    J=s.Matrix([[0,-I],[I,0]])\n    exact_current=(La*X)*J*(La*X).H*QB/hn(N)\n    eq(tag+\' observed current phase\',Wop,exact_current)\n    eq(tag+\' observed current trace\',s.trace(Wop),-2*s.im(OX[0,1])/hn(N))\n    product=(s.trace(Wop)**2-s.trace(Wop**2))/2\n    eq(tag+\' signed product\',product,-s.det(OX)/hn(N)**2)\n    check(tag+\' exact two current directions\',Wop.rank()==2)\n    eps2=s.cancel(EF[0,0]*EF[1,1]/hn(N)**2)\n    kdet=s.cancel(s.det(OX)/(EF[0,0]*EF[1,1]))\n    eq(tag+\' normalized area and signed product\',product,-eps2*kdet)\n    check(tag+\' area in (0,1]\',0<kdet<=1)\n    CAX=clean(CA*X)\n    eq(tag+\' first original conductor value\',CAX[:,0],coeff(rem(T(pp[N]),Qlo),2))\n    eq(tag+\' second original conductor value\',CAX[:,1],coeff(rem(T(pp[N+1]),Qlo),2))\n    # Complete lower quotient identities, independently using relation Grams.\n    ad,bd=bl[D],bl[D+1];t=D-2\n    dl=s.cancel(hn(D)/relnorm(Qlo,t));el=s.cancel(hn(D+1)/relnorm(Qlo,t+1))\n    eq(tag+\' lower last vector norm\',(ad.H*Gl*ad)[0],hn(D)*(1-dl))\n    eq(tag+\' lower raised vector norm\',(bd.H*Gl*bd)[0],hn(D+1)*(1-el)/el)\n    eq(tag+\' lower quotient parity\',(ad.H*Gl*bd)[0],0)\n    check(tag+\' complete lower ratios\',0<dl<1 and 0<el<1)\n    # Exact top conductor coefficients and orthogonal remainders.\n    A=s.Poly(T(pp[N]),Y).LC();B=s.Poly(T(pp[N+1]),Y).LC()\n    eq(tag+\' exact degree order N\',s.degree(T(pp[N]),Y),D)\n    eq(tag+\' exact degree order N1\',s.degree(T(pp[N+1]),Y),D+1)\n    moment=aa[0]*g**v+aa[1]*(-g)**v\n    eq(tag+\' exact top coefficient N\',A,moment*s.binomial(N,v))\n    eq(tag+\' exact top coefficient N1\',B,moment*s.binomial(N+1,v))\n    RN=s.expand(T(pp[N])-A*pp[D]);RP=s.expand(T(pp[N+1])-B*pp[D+1])\n    RNvec=coeff(RN,D+1);RPvec=coeff(RP,D+2)\n    RNnorm=(RNvec.H*gram_source(D)*RNvec)[0]\n    RPnorm=(RPvec.H*gram_source(D+1)*RPvec)[0]\n    ee=(ad.H*Gl*coeff(rem(RN,Qlo),2))[0]\n    check(tag+\' last-vector remainder Cauchy bound\',s.simplify(s.Abs(ee)**2-hn(D)*dl*RNnorm)<=0)\n    # Exact top-component projection and full two-column compression.\n    AA=s.Matrix.hstack(ad,bd);GG=AA.H*Gl*AA\n    YY=clean(AA.H*Gl*CAX)\n    eq(tag+\' complete test Gram\',(CAX.H*Gl*CAX),YY.H*GG.inv()*YY)\n    # Norm of conductor in the *complete* source Gamma basis; Frobenius is certified.\n    Tmat=s.Matrix.hstack(*(coeff(T(pp[j]),D+1) for j in range(N+1)))\n    Tnorm2=s.trace(s.diag(*(1/hn(j) for j in range(N+1)))*Tmat.H*gram_source(D)*Tmat)\n    check(tag+\' conductor norm positive\',s.simplify(Tnorm2)>0)\n    Tmat1=s.Matrix.hstack(*(coeff(T(pp[j]),D+2) for j in range(N+2)))\n    Tnorm21=s.simplify(s.trace(s.diag(*(1/hn(j) for j in range(N+2)))*Tmat1.H*gram_source(D+1)*Tmat1))\n    Tnorm2=s.simplify(Tnorm2)\n    bN2=s.cancel(Tnorm2*hn(N)/(s.Abs(A)**2*hn(D)))\n    bP2=s.cancel(Tnorm21*hn(N+1)/(s.Abs(B)**2*hn(D+1)))\n    xx=sqrt_up(bN2*dl/(1-dl)**2)\n    yy=sqrt_up(bP2*el/(1-el))\n    zz=sqrt_up(bN2*bP2*el/((1-dl)*(1-el)))\n    margin=s.cancel((1-xx)*(1-yy)-zz)\n    guard_record={\'x_bound\':str(xx),\'y_bound\':str(yy),\'cross_bound\':str(zz),\n                  \'margin\':str(margin),\'guard_passes\':bool(xx+yy+zz<=s.Rational(1,2))}\n    if xx<1 and yy<1 and margin>0:\n        A2=hn(D)*(1-dl);B2=hn(D+1)*(1-el)/el\n        bound=s.cancel(s.Abs(A*B)**2*A2*B2*margin**2/Tnorm2**2/(EF[0,0]*EF[1,1]))\n        check(tag+\' full finite two-plane lower bound\',0<bound<=kdet)\n        guard_record[\'area_lower_bound\']=str(bound)\n    # The prescribed full-current eigenclasses retain an exact complex formula after observation.\n    ar,br=EF[0,0],EF[1,1]\n    cc=clean(s.diag(1/s.sqrt(ar),1/s.sqrt(br))*OX*s.diag(1/s.sqrt(ar),1/s.sqrt(br)))\n    delta=s.simplify(s.det(cc));yy0=s.im(cc[0,1]);tt=s.trace(cc)\n    for sign in (1,-1):\n        vv=s.Matrix([1,sign*I])\n        actual=s.simplify((vv.H*cc*J*cc*vv)[0]/(vv.H*cc*vv)[0])\n        expected=s.simplify(-2*yy0+sign*2*delta/(tt-sign*2*yy0))\n        eq(tag+\' same observed class sign formula \'+str(sign),actual,expected)\n    guard_record[\'prescribed_plus_value_over_epsilon\']=str(s.simplify(-2*yy0+2*delta/(tt-2*yy0)))\n    guard_record[\'prescribed_minus_value_over_epsilon\']=str(s.simplify(-2*yy0-2*delta/(tt+2*yy0)))\n    check(tag+\' full observed conductor comparison\',isnonneg(Tnorm2*OX-CAX.H*Gl*CAX))\n    # Complete metric projection estimate for first outgoing vector.\n    Kvec=clean(s.Matrix.hstack(*La.nullspace()))\n    HK=clean(Kvec.H*G*Kvec)\n    alpha=s.cancel((bs[N].H*G*Kvec*HK.inv()*Kvec.H*G*bs[N])[0]/EF[0,0])\n    alpha_bound=s.cancel(hn(N)**2*Tnorm2/(EF[0,0]*s.Abs(A)**2*relnorm(Qlo,t)))\n    check(tag+\' first outgoing kernel projection bound\',0<=alpha<=alpha_bound)\n    WK=clean(HK.inv()*Kvec.H*current*Kvec)\n    # Its operator norm is bounded by 2 eps sqrt(alpha); verify via characteristic if rank<=2.\n    check(tag+\' kernel current rank\',WK.rank()<=2)\n    # Mass and nonunitary coordinate congruences.\n    Z=s.Matrix([[1,I/3,0,0],[0,1,s.Rational(1,4),0],[0,0,1,-I/5],[0,0,0,1]])\n    Gz=clean(Z.H*G*Z);Mz=clean(Z.inv()*M*Z);Laz=clean(La*Z)\n    QBz=clean(clean(Laz*clean(Gz.inv())*Laz.H).inv())\n    eq(tag+\' nonunitary observed metric\',QBz,QB)\n    eq(tag+\' nonunitary physical action\',I*(Gz*Mz-Mz.H*Gz),Z.H*current*Z)\n    for mass in (s.Integer(3),s.Rational(7,2)):\n        Qmass=clean(clean(La*(mass*G).inv()*La.H).inv())\n        eq(tag+\' retained source mass \'+str(mass),Qmass,mass*QB)\n        eq(tag+\' current endomorphism mass \'+str(mass),(Qmass.inv()*(mass*Wform)),Wop)\n    print(\'DONE\',tag,flush=True,file=sys.stderr)\n    records.append({\'fixture\':tag,\'q\':4,\'lower_q\':2,\'N\':N,\'v\':v,\'observed_rank\':La.rows,\n                    \'area_ratio\':str(kdet),\'dominance_guard\':guard_record,\'alpha\':str(alpha),\'alpha_bound\':str(alpha_bound),\n                    \'current_trace\':str(s.simplify(s.trace(Wop))),\n                    \'current_positive_negative_product\':str(s.simplify(product))})\n    if any(s.simplify(z)!=0 for z in (La*X)*s.Matrix([[0,1],[1,0]])*(La*X).H*QB/hn(N)-Wop):\n        controls.append(tag+\': discarded y-coordinate imaginary phase rejected\')\n\nfor z in [\n (s.Rational(1,4),s.Integer(3),(1,1),0,3,\'native-shaped-even-N3\',False),\n (s.Rational(1,4),s.Integer(3),(1,-1),1,4,\'native-shaped-odd-N4\',True),\n (s.Rational(1,3),s.Integer(2),(1,I),0,5,\'complex-conductor-N5\',False),\n (s.Integer(100),s.Rational(1,100),(1,I),0,4,\'aux-smallshift-N4\',True),\n (s.Integer(100),s.Rational(1,100),(1,1),0,6,\'aux-smallshift-N6\',False),\n]:fixture(*z)\n# General complex 2-plane formula, including non-real overlap.\na,b,x,y,e=s.symbols(\'a b x y e\',real=True)\nK=s.Matrix([[a,x+I*y],[x-I*y,b]])\nJ=s.Matrix([[0,-I],[I,0]])\nW=e*J*K\nz=s.Symbol(\'z\')\neq(\'general two-plane characteristic\',W.charpoly(z).as_expr(),z*z+2*e*y*z-e*e*(a*b-x*x-y*y))\n# A single preserved norm does not preserve area or an indefinite sign pair.\nparallel=s.Matrix([[s.Rational(1,2),s.Rational(1,2)],[s.Rational(1,2),s.Rational(1,2)]])\ncheck(\'positive separate diagonal norms\',parallel[0,0]>0 and parallel[1,1]>0)\ncheck(\'parallel observation loses signed rank\',s.det(parallel)==0)\ncontrols.append(\'separate positive column norms do not imply positive area\')\n# Factorial cancellation includes the actual leading coefficient and full Gamma norms.\nfor n in range(5,11):\n for v in range(0,4):\n  lhs=s.binomial(n,v)**2*hn(n-v)/hn(n)\n  rhs=s.prod(s.Rational(2*(n-j),2*(n-j)-1) for j in range(v))/s.factorial(v)**2\n  eq(f\'factorial leading coefficient n{n}v{v}\',lhs,rhs)\n\n# Exact polynomial/algebraic parts of the propagator proof.\ntm,ee,ss=s.symbols(\'tm ee ss\',positive=True)\ninteg=s.integrate((1+(tm-ss)*ee)*(1+ss*ee)/(1+tm*ee),(ss,0,tm))\neq(\'complete Duhamel ratio integral\',integ,tm+ee**2*tm**3/(6*(1+tm*ee)))\neq(\'Duhamel majorant remainder\',tm+ee*tm**2/6-integ,ee*tm**2/(6*(1+tm*ee)))\nxx=s.symbols(\'xx\',nonnegative=True)\nShear=s.Matrix([[1,I*xx],[0,1]])\neq(\'exact shear squared characteristic\',(Shear.H*Shear).charpoly(z).as_expr(),z*z-(2+xx*xx)*z+1)\nsplus=(s.sqrt(xx*xx+4)+xx)/2\nsminus=(s.sqrt(xx*xx+4)-xx)/2\neq(\'shear norm eigenvalue\',(splus*splus)**2-(2+xx*xx)*splus*splus+1,0)\neq(\'complete shear singular product\',splus*sminus,1)\nRR=s.Matrix([[1+I,2,0],[0,0,0],[0,0,0]])\nzz=s.trace(RR)\nfor power in range(1,10):eq(\'rank-one full exponential coefficient \'+str(power),RR**power,zz**(power-1)*RR)\n# A measured word exponential need not equal its separately compressed exponential.\nCC=s.Matrix([[1,I,1],[-I,0,2],[1,2,-1]])\nMM=CC+s.Matrix([[0,5,0],[0,0,0],[0,0,0]])\nJJ=s.Matrix([[1,0],[0,1],[0,0]])\nif clean(JJ.H*MM**2*JJ)!=clean((JJ.H*MM*JJ)**2):\n    controls.append(\'measurement of full evolution is not the compressed semigroup\')\nelse:raise ArithmeticError(\'semigroup negative control did not differ\')\nroot=Path(__file__).resolve().parent.parent\nreceipt={\'passed\':True,\'exact_checks\':len(checks),\'negative_controls\':len(controls),\n \'scope\':\'Exact finite auxiliary Gamma-polynomial sources and complex observations; no native xi zero or period evaluation.\',\n \'checks\':checks,\'controls\':controls,\'fixtures\':records,\n \'script_sha256\':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}\ntext=json.dumps(receipt,indent=2,sort_keys=True)\nif len(sys.argv)>1:Path(sys.argv[1]).write_text(text+\'\\n\')\nelse:print(text)\n', 'current/constant_interval.py': '#!/usr/bin/env python3\n"""Outward rational certification of the fixed elliptic current-return coefficient.\nNo native arithmetic zero or period is sampled.\n"""\nfrom fractions import Fraction as F\nfrom math import isqrt\nfrom decimal import Decimal, localcontext, ROUND_FLOOR, ROUND_CEILING\nimport json,sys\nfrom pathlib import Path\nS=10**100\nN=4096\n\ndef ceildiv(a,b):return -((-a)//b)\ndef elliptic(r):\n    m=1-r*r;ml,md=m.numerator,m.denominator\n    lo=hi=S;kslo=kshi=S;eslo=eshi=0\n    for n in range(N):\n        num=ml*(2*n+1)**2;den=md*4*(n+1)**2\n        lo=lo*num//den;hi=ceildiv(hi*num,den)\n        kslo+=lo;kshi+=hi\n        eslo+=lo//(2*n+1);eshi+=ceildiv(hi,2*n+1)\n    num=ml*(2*N+1)**2;den=md*4*(N+1)**2\n    nexthi=ceildiv(hi*num,den)\n    ktail=ceildiv(nexthi*md,md-ml)\n    etail=ceildiv(ktail,2*N+1)\n    return (F(kslo,S),F(kshi+ktail,S)),(F(S-eshi-etail,S),F(S-eslo,S))\n\ndef atan_interval(x,n):\n    val=sum(((-1)**j*x**(2*j+1)/F(2*j+1) for j in range(n)),F(0))\n    tail=x**(2*n+1)/F(2*n+1)\n    return (val,val+tail) if n%2==0 else (val-tail,val)\ndef add(a,b):return(a[0]+b[0],a[1]+b[1])\ndef sub(a,b):return(a[0]-b[1],a[1]-b[0])\ndef mul(a,b):\n    v=[x*y for x in a for y in b];return min(v),max(v)\ndef div(a,b):\n    if b[0]<=0:raise ArithmeticError(\'nonpositive denominator\')\n    return mul(a,(F(1)/b[1],F(1)/b[0]))\ndef sqrt_interval(a):\n    sc=10**100\n    lo=isqrt(a[0].numerator*sc*sc//a[0].denominator)\n    hi=isqrt(a[1].numerator*sc*sc//a[1].denominator)+1\n    return F(lo,sc),F(hi,sc)\ndef log_point(x,n=80):\n    x=F(x)\n    if x<1:\n        lo,hi=log_point(1/x,n);return -hi,-lo\n    y=(x-1)/(x+1)\n    yl=y.numerator*S//y.denominator;yu=ceildiv(y.numerator*S,y.denominator)\n    tl,tu=yl,yu;lo=hi=0\n    for j in range(n):\n        lo+=2*tl//(2*j+1);hi+=ceildiv(2*tu,2*j+1)\n        tl=tl*yl*yl//(S*S);tu=ceildiv(tu*yu*yu,S*S)\n    tail=ceildiv(2*tu*S*S,(2*n+1)*(S*S-yu*yu))\n    return F(lo,S),F(hi+tail,S)\n\ndef log_interval(a):return log_point(a[0])[0],log_point(a[1])[1]\ndef scaledout(a,places=60):\n    def out(x,rounding):\n        with localcontext() as c:\n            c.prec=places+25;c.rounding=rounding\n            return format((Decimal(x.numerator)/Decimal(x.denominator)).quantize(Decimal(1).scaleb(-places)),\'f\')\n    return [out(a[0],ROUND_FLOOR),out(a[1],ROUND_CEILING)]\nrlo=F(\'0.16010167095771835588\');rhi=F(\'0.16010167095771835589\')\nKl,El=elliptic(rlo);Ku,Eu=elliptic(rhi)\nfl=sub(El,mul((2*rlo,2*rlo),Kl));fu=sub(Eu,mul((2*rhi,2*rhi),Ku))\nif not(fl[0]>0 and fu[1]<0):raise ArithmeticError(\'root bracket failed\')\npi=sub(mul((16,16),atan_interval(F(1,5),100)),mul((4,4),atan_interval(F(1,239),32)))\nr=(rlo,rhi);kap=sqrt_interval((1-rhi*rhi,1-rlo*rlo));Eh=(El[0],Eu[1]);E=div(mul(pi,Eh),(2,2))\nratio=div(mul(kap,add((1,1),r)),mul(E,E))\na1=log_interval(ratio);a0=log_interval(div((4,4),pi))\nret=mul((2,2),sub(a0,a1))\nif not(a1[0]>0 and a0[0]>a1[1]):raise ArithmeticError(\'positive profile gap\')\nrecord={\'method\':\'Integer outward recurrence, 4096 elliptic terms with positive geometric tails; rational Machin pi bounds; integer square roots; rational atanh-series logarithms.\',\n \'r\':scaledout(r,20),\'root_test_low\':scaledout(fl,60),\'root_test_high\':scaledout(fu,60),\n \'psi0\':scaledout(a0,40),\'psi1\':scaledout(a1,40),\'two_psi_gap\':scaledout(ret,40), \'physical_flow_return\':scaledout(sub(mul((2,2),a0),(F(1,4),F(1,4))),40), \'short_time_margin\':scaledout(sub((F(1,4),F(1,4)),a0),40),\n \'scope\':\'Universal reference-profile coefficient only; no xi-zero or period evaluation.\'}\np=Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).resolve().parents[1]/\'state/CURRENT_CONSTANT.json\'\np.write_text(json.dumps(record,indent=2)+\'\\n\')\nprint(json.dumps(record,indent=2))\n', 'current/propagator_numerics.py': '#!/usr/bin/env python3\n"""80-digit noninterval diagnostics for the proved propagator inequalities."""\nfrom pathlib import Path\nimport json,sys\nimport mpmath as m\nm.mp.dps=80\nnames=[]\ndef opnorm(A):\n    ev=m.eighe(A.H*A,eigvals_only=True)\n    return m.sqrt(max(m.mpf(0),ev[-1] if isinstance(ev,list) else ev[ev.rows-1]))\ndef ok(name,p):\n    if not p:raise ArithmeticError(name)\n    names.append(name)\ndef bound(C,R,t):\n    eps=opnorm(R);z=sum(R[i,i] for i in range(R.rows));c=opnorm(C)\n    delta=c*m.exp(t*abs(z))*(t+eps*t*t/6)\n    if not delta<1:raise ArithmeticError(\'outside finite bound guard\')\n    E=m.exp(t*abs(z))*(delta/(1-delta)+t*abs(z)/2)\n    return E,eps\nC=m.matrix([[1,1j,1],[-1j,0,2],[1,2,-1]])\nmodels=[m.matrix([[0,15,0],[0,0,0],[0,0,0]]),\n        m.matrix([[m.mpc(\'0.1\',\'0.2\'),15,0],[0,0,0],[0,0,0]])]\nB=m.matrix([[1/m.sqrt(2),1/m.sqrt(6)],[-1j/m.sqrt(2),1j/m.sqrt(6)],[0,-2/m.sqrt(6)]])\nfor n,R in enumerate(models):\n    ok(f\'original rank-one identity {n}\',opnorm(R*R-sum(R[j,j] for j in range(3))*R)<m.mpf(\'1e-70\'))\n    CB=B.H*C*B;RB=B.H*R*B\n    for den in (1000,200,50,20):\n        t=m.mpf(1)/den\n        E,eps=bound(C,R,t)\n        S=m.expm(1j*t*(C+R));first=m.eye(3)+1j*t*R\n        err=opnorm(S-first)/(1+t*eps)\n        ok(f\'whole noncommuting finite Duhamel bound {n}/{den}\',err<=E+m.mpf(\'1e-65\'))\n        EB,epsB=bound(CB,RB,t)\n        SB=m.expm(1j*t*(CB+RB));PB=B.H*S*B\n        firstB=m.eye(2)+1j*t*RB\n        errB=opnorm(SB-firstB)/(1+t*epsB)\n        ok(f\'observed intrinsic finite Duhamel bound {n}/{den}\',errB<=EB+m.mpf(\'1e-65\'))\n        measured=opnorm(PB-firstB)/(1+t*epsB)\n        bridge=E*(1+t*eps)/(1+t*epsB)\n        ok(f\'full original observation with retained ratio {n}/{den}\',measured<=bridge+m.mpf(\'1e-65\'))\n        ok(f\'measured versus intrinsic original propagation {n}/{den}\',opnorm(PB-SB)/(1+t*epsB)<=bridge+EB+m.mpf(\'1e-65\'))\nfor x in (m.mpf(\'0\'),m.mpf(\'0.1\'),m.mpf(\'1\'),m.mpf(\'10\'),m.mpf(\'100\')):\n    U=m.matrix([[1,1j*x],[0,1]])\n    ok(\'exact shear norm diagnostic \'+str(x),abs(opnorm(U)-(m.sqrt(x*x+4)+x)/2)<m.mpf(\'1e-65\'))\nout={\'passed\':True,\'checks\':len(names),\'precision_digits\':80,\n \'scope\':\'Numerical, not interval, diagnostics of complete finite inequalities on auxiliary complex matrices. Not native arithmetic or period data.\', \'names\':names}\npath=Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).resolve().parents[1]/\'state/PROPAGATOR_NUMERICAL.json\'\npath.write_text(json.dumps(out,indent=2)+\'\\n\')\nprint(json.dumps({\'passed\':True,\'checks\':len(names)},indent=2))\n'}

